INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7735352, 1275108, 29535, '<td valign="top">Love telescope photography and this is as perfect an entry for the challenge as you can ask for. Beautiful composition and processing, great detail on the moon itself. My winner!</td>', 'Love telescope photography and this is as perfect an entry for the challenge as you can ask for. Beautiful composition and processing, great detail on the moon itself. My winner!', '2022-12-23 06:15:09.000000', NULL, 1),
(7735353, 1275112, 29535, '<td valign="top">Beautiful snowscape capturing all the colours and contrast perfectly. Top 3 for me!</td>', 'Beautiful snowscape capturing all the colours and contrast perfectly. Top 3 for me!', '2022-12-23 06:15:35.000000', NULL, 1),
(7735354, 1274901, 29535, '<td valign="top">One of my top 3! These shots are never easy with the lighting, and the detail you''ve managed to get is wonderful as well as the incredible trees as a subject. Well done!</td>', 'One of my top 3! These shots are never easy with the lighting, and the detail you''ve managed to get is wonderful as well as the incredible trees as a subject. Well done!', '2022-12-23 06:16:17.000000', NULL, 1),
(7735355, 1275134, 29535, '<td valign="top">I''m not usually a fan of drone shots but the composition here is inspired and the detail is incredible. Great job, top 5.</td>', 'I''m not usually a fan of drone shots but the composition here is inspired and the detail is incredible. Great job, top 5.', '2022-12-23 06:16:45.000000', NULL, 1),
(7735356, 1275123, 29535, '<td valign="top">Beautiful amount of detail capture on the feathers and a great composition. Good job!</td>', 'Beautiful amount of detail capture on the feathers and a great composition. Good job!', '2022-12-23 06:17:03.000000', NULL, 1),
(7735357, 1275131, 29535, '<td valign="top">Very cool composition and sunset capture.</td>', 'Very cool composition and sunset capture.', '2022-12-23 06:17:20.000000', NULL, 1),
(7735358, 1275084, 29535, '<td valign="top">I like this, simple concept and good execution. Love the blurry branches.</td>', 'I like this, simple concept and good execution. Love the blurry branches.', '2022-12-23 06:17:44.000000', NULL, 1),
(7735385, 1275133, 29535, '<td valign="top">A perfect interpretation of the challenge and a lovely seascape shot. Thank you!</td>', 'A perfect interpretation of the challenge and a lovely seascape shot. Thank you!', '2022-12-24 08:31:53.000000', NULL, 1),
(7735386, 1275071, 29535, '<td valign="top">I love the unusual composition you''ve chosen here and that fog must''ve been amazing to see.</td>', 'I love the unusual composition you''ve chosen here and that fog must''ve been amazing to see.', '2022-12-24 08:32:29.000000', NULL, 1),
(7735387, 1275135, 29535, '<td valign="top">Great spot and a perfect entry for the challenge. Great job!</td>', 'Great spot and a perfect entry for the challenge. Great job!', '2022-12-24 08:32:45.000000', NULL, 1),
(7735388, 1275088, 29535, '<td valign="top">A pin sharp shot of one of my favourite animals. Good job! I''m curious to see if another crop or composition was possible with the original, I feel this would benefit from a bit more breathing space on the right.</td>', 'A pin sharp shot of one of my favourite animals. Good job! I''m curious to see if another crop or composition was possible with the original, I feel this would benefit from a bit more breathing space on the right.', '2022-12-24 08:33:52.000000', NULL, 1),
(7735389, 1275117, 29535, '<td valign="top">The kind of architectural/street shot I dream of being able to pick out. Good job!</td>', 'The kind of architectural/street shot I dream of being able to pick out. Good job!', '2022-12-24 08:34:16.000000', NULL, 1),
(7735390, 1275124, 29535, '<td valign="top">This is an unusual composition but I think it works! I love the contrast between the steeple and the snow.</td>', 'This is an unusual composition but I think it works! I love the contrast between the steeple and the snow.', '2022-12-24 08:34:55.000000', NULL, 1),
(7735414, 1275128, 29535, '<td valign="top">The sky is actually really nice here. Compositionally you''ve managed to make something interesting out of a relatively banal subject which is a great skill to have. I''d like to have maybe seen the tower itself a little brighter everything seems a tad dark.</td>', 'The sky is actually really nice here. Compositionally you''ve managed to make something interesting out of a relatively banal subject which is a great skill to have. I''d like to have maybe seen the tower itself a little brighter everything seems a tad dark.', '2022-12-24 14:28:54.000000', NULL, 1),
(7735440, 1274985, 91360, '<td valign="top">wonderful!</td>', 'wonderful!', '2022-12-25 11:53:09.000000', NULL, 1),
(7735441, 1275119, 141319, '<td valign="top">I feel the focus is not on the (distant) village, but on the foreground and the power line</td>', 'I feel the focus is not on the (distant) village, but on the foreground and the power line', '2022-12-25 13:02:24.000000', NULL, 1),
(7735442, 1275124, 141319, '<td valign="top">Nice,</td>', 'Nice,', '2022-12-25 13:03:06.000000', NULL, 1),
