(7735444, 1275128, 141319, '<td valign="top">For this challenge I am expecting things "in the distance", not "zoomed in".</td>', 'For this challenge I am expecting things "in the distance", not "zoomed in".', '2022-12-25 13:05:12.000000', NULL, 1),
(7735445, 1275134, 141319, '<td valign="top">Oh goodness, it took a while to see the people and see how large the writing was!! What a great entry for the challenge</td>', 'Oh goodness, it took a while to see the people and see how large the writing was!! What a great entry for the challenge', '2022-12-25 13:06:35.000000', NULL, 1),
